        ? "in_review"
        : "draft";

    await sql`
      update journeys
      set plan = ${JSON.stringify(legacy)},
          draft_plan = ${JSON.stringify(nextDraft)},
          journey_status = ${nextStatus},
          plan_updated_at = now(),
          updated_at = now()
      where id = ${journey.id}
    `;
    return true;
  });

