const seed = (): JournalSnapshot => ({
  onboarded: false,
  profile: emptyProfile(),
  consults: [],
  nutrition: [],
  tasks: [],
  days: {},
  monthNotes: {},
  plan: emptyPlan(),
  journeyPlan: emptyJourneyPlan(),
