import { addDays, format, parseISO, subDays } from "date-fns";
import type {
  DoctorAlert,
  JourneyActionProgress,
  JourneyModule,
  JourneyModuleResponse,
  JourneyPlanV2,
  JourneyQuestion,
} from "./types";

export type PreConsultHighlight = {
  label: string;
  value: string;
};

export type PreConsultModuleSummary = {
  moduleId: string;
  title: string;
  responseCount: number;
  daysWithResponses: number;
  lastResponseOn: string;
  highlights: PreConsultHighlight[];
};

export type PreConsultSummary = {
  days: number;
  periodStart: string;
  totalResponses: number;
  daysWithResponses: number;
  modulesWithResponses: number;
  openCareActions: number;
  alertsInPeriod: number;
  moduleSummaries: PreConsultModuleSummary[];
  upcomingAppointments: Array<{
    id: string;
    label: string;
    date: string;
  }>;
};

export function buildPreConsultSummary({
  plan,
  responses,
  progress,
  alerts,
  days,
  now = new Date(),
}: {
  plan: JourneyPlanV2;
  responses: JourneyModuleResponse[];
  progress: JourneyActionProgress[];
  alerts: DoctorAlert[];
  days: number;
  now?: Date;
}): PreConsultSummary {
  const start = subDays(now, Math.max(1, days) - 1);
  start.setHours(0, 0, 0, 0);
  const startKey = format(start, "yyyy-MM-dd");
  const todayKey = format(now, "yyyy-MM-dd");

  const recentResponses = responses.filter(
    (response) => response.occurredOn >= startKey && response.occurredOn <= todayKey,
  );

  const moduleSummaries = plan.modules
    .filter((module) => module.enabled)
    .map((module) => summarizeModule(module, recentResponses))
    .filter((summary) => summary.responseCount > 0);

  const upcomingAppointments = plan.appointments
    .filter(
      (appointment) =>
        appointment.status !== "cancelled" &&
        appointment.status !== "completed",
    )
    .map((appointment) => ({
      appointment,
      date: resolvedAppointmentDateForSummary(plan, appointment),
    }))
    .filter((item) => item.date && item.date >= todayKey)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(0, 5)
    .map(({ appointment, date }) => ({
      id: appointment.id,
      label:
        appointment.professional ||
        appointmentLabel(appointment.type),
      date,
    }));

  return {
    days,
    periodStart: startKey,
    totalResponses: recentResponses.length,
    daysWithResponses: new Set(recentResponses.map((response) => response.occurredOn)).size,
    modulesWithResponses: moduleSummaries.length,
    openCareActions: openCareActionCountForSummary(plan, progress),
    alertsInPeriod: alerts.filter(
      (alert) => alert.occurredOn >= startKey && alert.occurredOn <= todayKey,
    ).length,
    moduleSummaries,
    upcomingAppointments,
  };
}

function summarizeModule(
  module: JourneyModule,
  responses: JourneyModuleResponse[],
): PreConsultModuleSummary {
  const moduleResponses = responses
    .filter((response) => response.moduleId === module.id)
    .sort((a, b) => b.occurredOn.localeCompare(a.occurredOn));

  return {
    moduleId: module.id,
    title: module.title,
    responseCount: moduleResponses.length,
    daysWithResponses: new Set(moduleResponses.map((response) => response.occurredOn)).size,
    lastResponseOn: moduleResponses[0]?.occurredOn ?? "",
    highlights: module.questions
      .map((question) => summarizeQuestion(question, moduleResponses))
      .filter((item): item is PreConsultHighlight => Boolean(item))
      .slice(0, 5),
  };
}

function summarizeQuestion(
  question: JourneyQuestion,
  responses: JourneyModuleResponse[],
): PreConsultHighlight | null {
  const values = responses
    .map((response) => ({
      response,
      value: response.answers[question.id],
    }))
    .filter(
      ({ value }) =>
        value !== undefined &&
        value !== null &&
        value !== "" &&
        (!Array.isArray(value) || value.length > 0),
    );

  if (!values.length) return null;

  if (
    question.type === "scale" ||
    question.type === "number" ||
    question.type === "duration"
  ) {
    const numbers = values
      .map(({ value }) => (typeof value === "number" ? value : Number.NaN))
      .filter(Number.isFinite);
    if (!numbers.length) return null;
    const average = numbers.reduce((sum, value) => sum + value, 0) / numbers.length;
    const suffix = question.type === "duration" ? " min" : "";
    return {
      label: question.label,
      value: `média ${formatNumber(average)}${suffix} · faixa ${formatNumber(
        Math.min(...numbers),
      )}–${formatNumber(Math.max(...numbers))}${suffix}`,
    };
  }

  if (question.type === "boolean" || question.type === "event") {
    const yes = values.filter(({ value }) => value === true).length;
    const no = values.filter(({ value }) => value === false).length;
    return {
      label: question.label,
      value: `Sim ${yes} · Não ${no}`,
    };
  }

  if (question.type === "single_choice" || question.type === "emotion") {
    const counts = new Map<string, number>();
    for (const { value } of values) {
      if (typeof value !== "string") continue;
      counts.set(value, (counts.get(value) ?? 0) + 1);
    }
    const top = [...counts.entries()].sort((a, b) => b[1] - a[1])[0];
    if (!top) return null;
    const label =
      question.options?.find((option) => option.id === top[0])?.label ?? top[0];
    return {
      label: question.label,
      value: `${label} · ${top[1]} de ${values.length}`,
    };
  }

  if (question.type === "multiple_choice") {
    const counts = new Map<string, number>();
    for (const { value } of values) {
      if (!Array.isArray(value)) continue;
      for (const item of value) {
        counts.set(item, (counts.get(item) ?? 0) + 1);
      }
    }
    const top = [...counts.entries()].sort((a, b) => b[1] - a[1])[0];
    if (!top) return null;
    const label =
      question.options?.find((option) => option.id === top[0])?.label ?? top[0];
    return {
      label: question.label,
      value: `${label} · ${top[1]} registros`,
    };
  }

  const latest = values
    .sort((a, b) => b.response.occurredOn.localeCompare(a.response.occurredOn))[0];
  if (!latest) return null;
  const formatted = formatAnswerForSummary(question, latest.value);
  return {
    label: question.label,
    value: formatted.length > 180 ? `${formatted.slice(0, 177)}…` : formatted,
  };
}

function openCareActionCountForSummary(
  plan: JourneyPlanV2,
  progress: JourneyActionProgress[],
): number {
  const completed = new Set(
    progress
      .filter((item) => item.status === "completed")
      .map((item) => `${item.actionType}:${item.actionId}`),
  );
  const tasks = plan.tasks.filter(
    (task) => !completed.has(`task:${task.id}`),
  ).length;
  const exams = plan.exams.filter(
    (exam) => !completed.has(`exam:${exam.id}`),
  ).length;
  return tasks + exams;
}

function resolvedAppointmentDateForSummary(
  plan: JourneyPlanV2,
  appointment: JourneyPlanV2["appointments"][number],
): string {
  if (appointment.date) return appointment.date;
  if (plan.startDate && appointment.offsetDays != null) {
    return format(
      addDays(parseISO(plan.startDate), appointment.offsetDays),
      "yyyy-MM-dd",
    );
  }
  return "";
}

function formatAnswerForSummary(
  question: JourneyQuestion,
  value: JourneyModuleResponse["answers"][string],
): string {
  if (value === null || value === undefined) return "—";
  if (question.type === "boolean" || question.type === "event") {
    return value === true ? "Sim" : value === false ? "Não" : String(value);
  }
  if (question.type === "single_choice" || question.type === "emotion") {
    if (typeof value !== "string") return String(value);
    return question.options?.find((option) => option.id === value)?.label ?? value;
  }
  if (question.type === "multiple_choice") {
    if (!Array.isArray(value)) return String(value);
    return value
      .map(
        (item) =>
          question.options?.find((option) => option.id === item)?.label ?? item,
      )
      .join(", ");
  }
  if (question.type === "duration") {
    return typeof value === "number" ? `${value} min` : String(value);
  }
  if (Array.isArray(value)) return value.join(", ");
  return String(value);
}

function appointmentLabel(
  type: JourneyPlanV2["appointments"][number]["type"],
): string {
  if (type === "doctor") return "Consulta médica";
  if (type === "nutrition") return "Nutricionista";
  if (type === "psychology") return "Psicologia";
  if (type === "nursing") return "Enfermagem";
  return "Outro encontro";
}

function formatNumber(value: number): string {
  return Number.isInteger(value) ? String(value) : value.toFixed(1).replace(".", ",");
}

export function isGrokEmbedderOrigin(origin: string): boolean {
  try {
    const url = new URL(origin);
    if (url.protocol !== "https:" && url.protocol !== "http:") return false;
    const host = url.hostname.toLowerCase();
    if (host === "grok.com" || host.endsWith(".grok.com")) return true;
    if (host === "localhost" || host === "127.0.0.1" || host === "[::1]") return true;
    return false;
  } catch {
    return false;
  }
}

export function isSandboxPreviewGuestHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return host === "grok-sandbox.com" || host.endsWith(".grok-sandbox.com");
}

function isRemintPreviewPair(guestHost: string, parentHost: string): boolean {
  const guest = guestHost.toLowerCase();
  const parent = parentHost.toLowerCase();
  const sep = ".preview.";
  const i = guest.indexOf(sep);
  if (i <= 0) return false;
  const label = guest.slice(0, i);
  const rest = guest.slice(i + sep.length);
  if (label.includes(".") || !rest.includes(".")) return false;
  return parent === rest || parent === `grok.${rest}`;
}

export function resolveParentEmbedderOrigin(
  parentIsSelf: boolean,
  referrer: string,
  ancestorOrigin?: string | null,
  guestHostname: string = "",
): string | null {
  if (parentIsSelf) return null;
  for (const candidate of [referrer, ancestorOrigin ?? ""].filter(Boolean)) {
    try {
      const url = new URL(
        candidate.includes("://") ? candidate : `https://${candidate}`,
      );
      if (url.protocol !== "https:" && url.protocol !== "http:") continue;
      if (isGrokEmbedderOrigin(url.origin)) return url.origin;
      if (
        isSandboxPreviewGuestHost(guestHostname) ||
        isRemintPreviewPair(guestHostname, url.hostname)
      ) {
        return url.origin;
      }
    } catch {
      // try next candidate
    }
  }
  return null;
}

/**
 * Guest side of the grok-web ↔ sandbox preview postMessage bridge.
 *
 * Activates only when this page is framed by an allowlisted Grok embedder.
 * Top-level runs (download/export, local `npm run dev`, deployed sites) noop.
 */

import { z } from "zod";
import { resolveParentEmbedderOrigin } from "./preview-embedder-origin";

export {
  isGrokEmbedderOrigin,
  isSandboxPreviewGuestHost,
  resolveParentEmbedderOrigin,
} from "./preview-embedder-origin";

export const PREVIEW_BRIDGE_CHANNEL = "grok-preview-bridge" as const;
export const PREVIEW_BRIDGE_VERSION = 1 as const;

const EnvelopeSchema = z.object({
  channel: z.literal(PREVIEW_BRIDGE_CHANNEL),
  version: z.number().int().positive(),
  type: z.string().min(1),
});

const HelloSchema = EnvelopeSchema.extend({
  type: z.literal("hello"),
});

const NavigateSchema = EnvelopeSchema.extend({
  type: z.literal("navigate"),
  path: z.string().min(1),
});

const HistorySchema = EnvelopeSchema.extend({
  type: z.literal("history"),
  delta: z.union([z.literal(-1), z.literal(1)]),
});

export type PreviewHostBridgeOptions = {
  /** Prefer the app router when available; falls back to history.pushState. */
  navigate?: (path: string) => void;
  /** Best-effort registered paths for host autosuggest (may be empty). */
  getRoutePaths?: () => string[];
};

export function isSafeBridgePath(path: string): boolean {
  if (!path.startsWith("/") || path.startsWith("//") || path.includes("\\")) {
    return false;
  }
  try {
    const resolved = new URL(path, "https://preview.invalid");
    return resolved.origin === "https://preview.invalid";
  } catch {
    return false;
  }
}

/**
 * Install host↔guest messaging. Returns a dispose function.
 * Noops (returns a no-op dispose) when not embedded under a Grok parent.
 */
export function installPreviewHostBridge(
  options: PreviewHostBridgeOptions = {},
): () => void {
  if (typeof window === "undefined") return () => {};

  const ancestorOrigin =
    typeof location.ancestorOrigins !== 'undefined' && location.ancestorOrigins.length > 0
      ? location.ancestorOrigins[0]
      : null;
  const parentOrigin = resolveParentEmbedderOrigin(
    window.parent === window,
    document.referrer,
    ancestorOrigin,
    window.location.hostname,
  );
  if (parentOrigin === null) return () => {};

  const ROOT_STATE_KEY = "__grokPreviewBridgeRoot";
  const originalPushState = window.history.pushState.bind(window.history);
  const originalReplaceState = window.history.replaceState.bind(window.history);

  const isAtHistoryRoot = () => {
    const state = window.history.state;
    return Boolean(
      state && typeof state === "object" && state[ROOT_STATE_KEY] === true,
    );
  };

  // Floor for chrome Back: only the first install in a fresh history stack is
  // root. Full document navigations reinstall this bridge on a deep URL; if we
  // re-stamped that entry as root, Back would no-op while earlier in-preview
  // history still exists. Preserve an existing tag (bfcache / SPA remount).
  try {
    const current = window.history.state;
    const alreadyTagged =
      current !== null &&
      typeof current === "object" &&
      Object.prototype.hasOwnProperty.call(current, ROOT_STATE_KEY);
    if (!alreadyTagged) {
      const isRoot = window.history.length <= 1;
      const marked =
        current && typeof current === "object"
          ? { ...current, [ROOT_STATE_KEY]: isRoot }
          : { [ROOT_STATE_KEY]: isRoot };
      originalReplaceState(marked, "", window.location.href);
    }
  } catch {
    // ignore if the document cannot be marked
  }

  const post = (message: object) => {
    window.parent.postMessage(message, parentOrigin);
  };

  const reportLocation = () => {
    post({
      channel: PREVIEW_BRIDGE_CHANNEL,
      version: PREVIEW_BRIDGE_VERSION,
      type: "location",
      path: window.location.pathname || "/",
      search: window.location.search,
      hash: window.location.hash,
    });
  };

  const reportRoutes = () => {
    const paths = options.getRoutePaths?.() ?? [];
    post({
      channel: PREVIEW_BRIDGE_CHANNEL,
      version: PREVIEW_BRIDGE_VERSION,
      type: "routes",
      paths,
    });
  };

  const defaultNavigate = (path: string) => {
    if (!isSafeBridgePath(path)) return;
    try {
      const url = new URL(path, window.location.origin);
      if (url.origin !== window.location.origin) return;
      const next = `${url.pathname}${url.search}${url.hash}`;
      window.history.pushState(window.history.state, "", next);
      window.dispatchEvent(new PopStateEvent("popstate", { state: window.history.state }));
    } catch {
      // ignore malformed paths
    }
  };

  const navigate = (path: string) => {
    if (!isSafeBridgePath(path)) return;
    if (options.navigate) {
      options.navigate(path);
      return;
    }
    defaultNavigate(path);
  };

  const announce = () => {
    reportLocation();
    reportRoutes();
    post({
      channel: PREVIEW_BRIDGE_CHANNEL,
      version: PREVIEW_BRIDGE_VERSION,
      type: "ready",
    });
  };

  const onMessage = (event: MessageEvent) => {
    if (event.source !== window.parent) return;
    if (event.origin !== parentOrigin) return;

    const envelope = EnvelopeSchema.safeParse(event.data);
    if (!envelope.success || envelope.data.version !== PREVIEW_BRIDGE_VERSION) return;

    // Host re-handshake: it may have (re)mounted after our install-time
    // announce, or asked before we hydrated. Announce again.
    if (envelope.data.type === "hello") {
      if (!HelloSchema.safeParse(event.data).success) return;
      announce();
      return;
    }

    if (envelope.data.type === "navigate") {
      const parsed = NavigateSchema.safeParse(event.data);
      if (!parsed.success) return;
      navigate(parsed.data.path);
      // Router navigations often update location asynchronously; report after a tick.
      queueMicrotask(reportLocation);
      return;
    }

    if (envelope.data.type === "history") {
      const parsed = HistorySchema.safeParse(event.data);
      if (!parsed.success) return;
      // Do not history.go(-1) off the first entry — that leaves the preview.
      if (parsed.data.delta === -1 && isAtHistoryRoot()) return;
      // Location sync comes from the popstate listener once history settles.
      window.history.go(parsed.data.delta);
    }
  };

  const onPopState = () => {
    reportLocation();
  };

  // Same-document `#` navigations fire hashchange, not popstate / pushState.
  const onHashChange = () => {
    reportLocation();
  };

  // Patch history so in-app SPA navigations sync the host address bar.
  window.history.pushState = (data, unused, url) => {
    const next =
      data && typeof data === "object"
        ? { ...data, [ROOT_STATE_KEY]: false }
        : data;
    originalPushState(next, unused, url);
    reportLocation();
  };
  window.history.replaceState = (data, unused, url) => {
    const next =
      isAtHistoryRoot()
        ? {
            ...(data && typeof data === "object" ? data : {}),
            [ROOT_STATE_KEY]: true,
          }
        : data;
    originalReplaceState(next, unused, url);
    reportLocation();
  };

  window.addEventListener("message", onMessage);
  window.addEventListener("popstate", onPopState);
  window.addEventListener("hashchange", onHashChange);

  announce();

  return () => {
    window.removeEventListener("message", onMessage);
    window.removeEventListener("popstate", onPopState);
    window.removeEventListener("hashchange", onHashChange);
    window.history.pushState = originalPushState;
    window.history.replaceState = originalReplaceState;
  };
}

/** Collect static path patterns from a TanStack route tree (best-effort). */
export function collectRoutePathsFromTree(routeTree: unknown): string[] {
  const paths = new Set<string>();

  const walk = (node: unknown) => {
    if (!node || typeof node !== "object") return;
    const record = node as {
      fullPath?: unknown;
      path?: unknown;
      children?: unknown;
    };
    const full =
      typeof record.fullPath === "string"
        ? record.fullPath
        : typeof record.path === "string"
          ? record.path
          : null;
    if (full !== null && full !== "") {
      paths.add(full.startsWith("/") ? full : `/${full}`);
    } else if (full === "") {
      paths.add("/");
    }
    const children = record.children;
    if (Array.isArray(children)) {
      for (const child of children) walk(child);
    } else if (children && typeof children === "object") {
      for (const child of Object.values(children as Record<string, unknown>)) {
        walk(child);
      }
    }
  };

  walk(routeTree);
  return [...paths];
}

